package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamPhysicsMechBank1 {
  private const val T = "යාන්ත්‍ර විද්‍යාව: මිනුම්, චලිතය, බලය, ශක්තිය හා ද්‍රවස්ථිතිය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "භෞතික විද්‍යාවේ යාන්ත්‍ර විද්‍යා කොටසට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("අන්තර්ජාතික ඒකක පද්ධතියේ (SI) ස්කන්ධය, දිග සහ කාලය යන මූලික රාශිවල සම්මත ඒකක පිළිවෙළින් මොනවාද?", "කිලෝග්‍රෑම් (kg), මීටරය (m), තත්පරය (s)", "ග්‍රෑම්, සෙන්ටිමීටර, මිනිත්තු", "නිව්ටන්, මීටර, පැය", "ටොන්, කිලෝමීටර, තත්පර", "මූලික SI ඒකක 7 අතරට kg, m, s අයත් වේ."),
    q("පහත දැක්වෙන භෞතික රාශි අතුරින් විශාලත්වයක් මෙන්ම නිශ්චිත දිශාවක් ද ඇති 'දෛශික රාශිය' කුමක්ද?", "විස්ථාපනය සහ ප්‍රවේගය", "දුර සහ වේගය", "ස්කන්ධය සහ කාලය", "උෂ්ණත්වය සහ කාර්යය", "අදිශ රාශිවලට විශාලත්වයක් පමණක් ඇති අතර දෛශිකවලට දිශාවක් ද ඇත."),
    q("කුඩා කම්බියක විෂ්කම්භය හෝ තුනී තහඩුවක ඝනකම 0.01 mm නිරවද්‍යතාවයකින් මැනීමට වඩාත් සුදුසු උපකරණය කුමක්ද?", "මයික්‍රෝමීටර ඉස්කුරුප්පු ආමානය", "මීටර කෝදුව", "වර්නියර් කැලිපරය", "දුනු තරාදිය", "වර්නියර් කැලිපරයේ කුඩාම මිනුම 0.1 mm (හෝ 0.05 mm) වන අතර මයික්‍රෝමීටරයේ 0.01 mm වේ."),
    q("වස්තුවක් පොළොව මතදී 1 kg ස්කන්ධයක් දරයි. එය ගුරුත්වය පොළොවෙන් 1/6 ක් වන සඳ මතට ගෙන ගිය විට එහි ස්කන්ධය කොපමණ වේද?", "1 kg (වෙනස් නොවේ)", "1/6 kg", "6 kg", "0 kg", "ස්කන්ධය පදාර්ථ ප්‍රමාණය මත රඳා පවතින බැවින් ස්ථානය අනුව වෙනස් නොවේ; බර පමණක් වෙනස් වේ."),
    q("පොළොව මත (g = 10 m s⁻²) ස්කන්ධය 60 kg වන අභ්‍යවකාශගාමියෙකුගේ බර කොපමණද?", "600 N", "60 N", "6 N", "6000 N", "බර W = mg = 60 kg × 10 m s⁻² = 600 N."),
    q("මෝටර් රථයක් උතුරු දිශාවට 30 m ක් ගමන් කර ඉන්පසු නැගෙනහිර දිශාවට 40 m ක් ගමන් කළේය. රථයේ මුළු විස්ථාපනය කීයද?", "50 m", "70 m", "10 m", "35 m", "පයිතගරස් ප්‍රමේයය අනුව √(30² + 40²) = √2500 = 50 m."),
    q("ධාවකයෙක් වෘත්තාකාර ධාවන පථයක (පරිධිය 400 m) සම්පූර්ණ වට 2 ක් දුවා ආරම්භක ස්ථානයේම නැවතුණි. ඔහුගේ ගමන් දුර හා විස්ථාපනය කීයද?", "දුර 800 m, විස්ථාපනය 0 m", "දුර 0 m, විස්ථාපනය 800 m", "දුර 400 m, විස්ථාපනය 400 m", "දෙකම 800 m", "ආරම්භක හා අවසාන ස්ථාන සමපාත වන විට ශුද්ධ විස්ථාපනය ශුන්‍ය වේ."),
    q("විස්ථාපන-කාල (s-t) ප්‍රස්තාරයක අනුක්‍රමණය (Slope) මඟින් ලබා දෙන භෞතික රාශිය කුමක්ද?", "ප්‍රවේගය", "ත්වරණය", "බලය", "ගම්‍යතාව", "ඒකාකාර ප්‍රවේගයෙන් යන වස්තුවක s-t ප්‍රස්තාරය සෘජු රේඛාවකි."),
    q("ප්‍රවේග-කාල (v-t) ප්‍රස්තාරයක අනුක්‍රමණය මඟින් සහ වක්‍රය යට ඇති වර්ගඵලය මඟින් පිළිවෙළින් නිරූපණය කරන්නේ මොනවාද?", "ත්වරණය සහ විස්ථාපනය", "විස්ථාපනය සහ ත්වරණය", "බලය සහ කාර්යය", "වේගය සහ කාලය", "v-t ප්‍රස්තාරයේ Δv/Δt = ත්වරණය ද වර්ගඵලය = විස්ථාපනය ද වේ."),
    q("නිසලතාවයෙන් ආරම්භ වන කාරයක් 2 m s⁻² ක ඒකාකාර ත්වරණයකින් තත්පර 6 ක් ගමන් කළ විට එහි අවසන් ප්‍රවේගය කීයද?", "12 m s⁻¹", "3 m s⁻¹", "8 m s⁻¹", "36 m s⁻¹", "v = u + at = 0 + (2 × 6) = 12 m s⁻¹."),
    q("නිසලතාවයෙන් ආරම්භ වී 4 m s⁻² ත්වරණයකින් තත්පර 5 ක් ගමන් කළ වස්තුවක් ගමන් කළ මුළු දුර කීයද?", "50 m", "20 m", "100 m", "40 m", "s = ut + ½at² = 0 + ½ × 4 × 5² = 50 m."),
    q("20 m s⁻¹ වේගයෙන් ගමන් කරන බස් රථයක් තිරිංග යෙදීමෙන් තත්පර 5 කින් නතර වේ. එහි මන්දනය කොපමණද?", "4 m s⁻²", "100 m s⁻²", "25 m s⁻²", "15 m s⁻²", "a = (v - u)/t = (0 - 20)/5 = -4 m s⁻² (මන්දනය 4 m s⁻²)."),
    q("ගොඩනැගිල්ලක මුදුනේ සිට නිදහසේ පහළට වැටෙන ගලක් තත්පර 3 කින් පොළොවේ ගැටේ නම් ගොඩනැගිල්ලේ උස කීයද? (g = 10 m s⁻²)", "45 m", "30 m", "90 m", "15 m", "h = ½gt² = ½ × 10 × 3² = 45 m."),
    q("සිරස්ව ඉහළට 30 m s⁻¹ ආරම්භක ප්‍රවේගයෙන් විසි කළ බෝලයක් උපරිම උසට ළඟා වීමට ගතවන කාලය කීයද? (g = 10 m s⁻²)", "3 s", "6 s", "30 s", "1.5 s", "උපරිම උසේදී v = 0; v = u - gt → 0 = 30 - 10t → t = 3 s."),
    q("නිව්ටන්ගේ පළමු චලිත නියමය මඟින් අර්ථ දැක්වෙන, වස්තුවක චලිත අවස්ථාව වෙනස් කිරීමට ඇති අකමැත්ත හඳුන්වන්නේ කුමන නමින්ද?", "අවස්ථිතිය (Inertia)", "ගම්‍යතාව", "ත්වරණය", "ආවේගය", "බස් රථය එක්වරම ඉදිරියට ඇදෙන විට මගීන් පිටුපසට විසි වන්නේ අවස්ථිතිය නිසාය."),
    q("බස් රථයක හදිසියේ තිරිංග තද කළ විට මගීන් ඉදිරියට ඇද වැටීම වැළැක්වීමට මෝටර් රථවල 'ආසන පටි' (Seat belts) පළඳින්නේ කුමන නියමය අනුවද?", "නිව්ටන්ගේ පළමු නියමය (අවස්ථිතිය)", "ආකිමිඩීස් නියමය", "ඕම් නියමය", "පැස්කල් නියමය", "වැදෙන කාලය වැඩි කර බලය අඩු කිරීමට නිව්ටන් දෙවන නියමය ද එයාර් බෑග්වලදී ක්‍රියා කරයි."),
    q("ස්කන්ධය 4 kg වන වස්තුවක් මත 24 N ක සම්ප්‍රයුක්ත බලයක් යෙදූ විට එහි ඇතිවන ත්වරණය කීයද?", "6 m s⁻²", "96 m s⁻²", "20 m s⁻²", "4 m s⁻²", "F = ma → a = F/m = 24 / 4 = 6 m s⁻²."),
    q("ස්කන්ධය 1200 kg වන රථයක් 15 m s⁻¹ ප්‍රවේගයෙන් ගමන් කරන විට එහි රේඛීය ගම්‍යතාව කීයද?", "18,000 kg m s⁻¹", "80 kg m s⁻¹", "1215 kg m s⁻¹", "9000 kg m s⁻¹", "P = mv = 1200 × 15 = 18,000 kg m s⁻¹."),
    q("නිව්ටන්ගේ තෙවන චලිත නියමයට අනුව ක්‍රියාව සහ ප්‍රතික්‍රියාව පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?", "සමාන විශාලත්වයෙන් යුතුව වෙනස් වස්තු දෙකක් මත ක්‍රියා කරයි", "සමාන විශාලත්වයෙන් යුතුව එකම වස්තුව මත ක්‍රියා කරයි", "ප්‍රතික්‍රියාව සැමවිටම ක්‍රියාවට වඩා කුඩා අගයක් ගනී", "ක්‍රියාව සහ ප්‍රතික්‍රියාව සැමවිටම එකම දිශාවට යොමු වේ", "වෙනස් වස්තු දෙකක් මත ක්‍රියා කරන බැවින් එකිනෙක අවලංගු නොවේ."),
    q("රොකට්ටුවක් අභ්‍යවකාශයේදී පවා ඉදිරියට තල්ලු වීම පැහැදිලි කරන මූලික භෞතික විද්‍යා නියමය කුමක්ද?", "නිව්ටන්ගේ තෙවන නියමය", "ආකිමිඩීස් මූලධර්මය", "හුක්ගේ ප්‍රත්‍යාස්ථතා නියමය", "බර්නූලි මූලධර්මය", "පසුපසට පිටවන වායු ධාරාව රොකට්ටුව මත ඉදිරියට සමාන ප්‍රතික්‍රියා බලයක් යොදයි."),
    q("කිසියම් වස්තුවක් මත ස්පර්ශ පෘෂ්ඨය ඔස්සේ චලිතයට විරුද්ධව ක්‍රියා කරන ඝර්ෂණ බලයට අදාළ වැදගත් නිරීක්ෂණයක් වන්නේ කුමක්ද?", "ඝර්ෂණ බලය ස්පර්ශ පෘෂ්ඨ වර්ගඵලය මත රඳා නොපවතී", "පෘෂ්ඨ වර්ගඵලය වැඩි විට ඝර්ෂණය දෙගුණ වේ", "ඝර්ෂණය සැමවිටම චලනයේ දිශාවට ක්‍රියා කරයි", "ලිහිසි තෙල් ඝර්ෂණය වැඩි කරයි", "සීමාකාරී ඝර්ෂණය පෘෂ්ඨවල ස්වභාවය හා අභිලම්බ ප්‍රතික්‍රියාව මත රඳා පවතී."),
    q("මෝටර් රථ ටයර්වල කට්ට (Treads) කපා තිබීම හා යන්ත්‍රවලට බෝල බෙයාරිං යෙදීම පිළිවෙළින් සිදු කරන්නේ කුමක්ද?", "ඝර්ෂණය වැඩි කිරීම සහ ඝර්ෂණය අඩු කිරීම", "දෙකම ඝර්ෂණය අඩු කිරීම", "දෙකම ඝර්ෂණය වැඩි කිරීම", "වේගය අඩු කිරීම", "වැසි දිනවල ටයර් කට්ට මගින් ජලය ඉවත් කර ලිස්සා යාම වළක්වයි; බෙයාරිං රෝලිං ඝර්ෂණයෙන් ඝර්ෂණය අඩු කරයි."),
    q("එකම සරල රේඛාවක විරුද්ධ දිශාවට ක්‍රියා කරන 18 N සහ 12 N බල දෙකක සම්ප්‍රයුක්ත බලය කොපමණද?", "6 N (18 N බලයේ දිශාවට)", "30 N", "15 N", "0 N", "ප්‍රතිවිරුද්ධ දිශාවලට ක්‍රියා කරන බැවින් සම්ප්‍රයුක්තය = 18 - 12 = 6 N."),
    q("සිරස්ව තබා ඇති ඒකාකාර දණ්ඩක මැදින් එල්ලා, වම් පස 0.4 m දුරින් 15 N බරක් එල්ලා ඇත. සමතුලිත කිරීමට දකුණු පස 0.6 m දුරින් එල්ලිය යුතු බර කීයද?", "10 N", "15 N", "20 N", "25 N", "වාමාවර්ත ඝූර්ණය = දක්ෂිණාවර්ත ඝූර්ණය → 15 × 0.4 = W × 0.6 → 6 = 0.6W → W = 10 N."),
    q("ඒකාකාර මීටර රූලක් මධ්‍ය ලක්ෂ්‍යයෙන් සමතුලිත වේ. රූලේ ගුරුත්ව කේන්ද්‍රය පිහිටන්නේ කුමන ලක්ෂ්‍යයේද?", "50 cm ලකුණෙහි", "0 cm ලකුණෙහි", "100 cm ලකුණෙහි", "25 cm ලකුණෙහි", "සමමිතික ඒකාකාර වස්තුවක ගුරුත්ව කේන්ද්‍රය එහි ජ්‍යාමිතික මධ්‍යයේ පිහිටයි."),
    q("විශාල බස් රථයකට වඩා රේසිං මෝටර් රථයක් වංගුවකදී පෙරළීමේ අවදානම අඩු (ස්ථායීතාව වැඩි) වීමට ප්‍රධාන හේතු දෙක මොනවාද?", "පහළ ගුරුත්ව කේන්ද්‍රය හා පුළුල් පාදම", "ඉහළ ගුරුත්ව කේන්ද්‍රය හා පටු පාදම", "සැහැල්ලු වහලය හා කුඩා විෂ්කම්භ රෝද", "පිටුපස එන්ජිම හා කළු පැහැති වීදුරු", "පහළ ගුරුත්ව කේන්ද්‍රය හා පුළුල් රෝද පාදම ස්ථායී සමතුලිතතාව වැඩි කරයි."),
    q("බල ඝූර්ණයේ (Moment of a force) SI ඒකකය කුමක්ද?", "නිව්ටන් මීටර (N m)", "නිව්ටන් (N)", "ජූල් (J)", "වොට් (W)", "ඝූර්ණය = බලය × ලම්භක දුර (කාර්යය සඳහා ජූල් ගන්නා අතර ඝූර්ණය සඳහා N m ගනී)."),
    q("දොරක් ඇරීමේදී සරනේරුවලින් හැකි තරම් දුරින් අගල් අල්ලුව (Handle) සවි කරන්නේ ඇයි?", "වැඩි දුරකින් අඩු බලයකින් ඝූර්ණය ලබා ගැනීමට", "දොරේ මුළු බර ප්‍රමාණය අඩු කර ගැනීමට", "සරනේරු අතර ඇතිවන ඝර්ෂණය වැඩි කිරීමට", "දොර පියනට වැඩි ආකර්ෂණීය පෙනුමක් දීමට", "τ = F × d නිසා d වැඩි විට අවශ්‍ය F අඩු වේ."),
    q("20 kg ස්කන්ධයක් ඇති පෙට්ටියක් 80 N බලයකින් තිරස්ව 5 m දුරක් ඇදගෙන යන විට සිදු කරන කාර්යය කීයද?", "400 J", "100 J", "1000 J", "16 J", "W = F × s = 80 × 5 = 400 J."),
    q("නිව්ටන් 500 ක බරැති පුද්ගලයෙක් 4 m උස පඩිපෙළක් තත්පර 10 කින් නගී. ඔහුගේ යාන්ත්‍රික ක්ෂමතාව (Power) කීයද?", "200 W", "2000 W", "50 W", "125 W", "කාර්යය = 500 × 4 = 2000 J; ක්ෂමතාව P = W/t = 2000 / 10 = 200 W."),
